// Kernel function
//--------------------------------------------------

int kernel_function(uint32_t arg_count, uint64_t args[]) {
  LOG_DBG("Enable dcache");
  ecall_dcache_enable();


  // Validate number of memory pool arguments
  if (arg_count != 5) {
    LOG_ERR("Invalid number of arguments! Expected %d, got %d...", 5, arg_count);
    return -1;
  }

  // Patch memory pool addresses
  kernel_function_mempools[KERNEL_FUNCTION_MEMPOOL_IDX_POOL_DDR_CONST].addr = args[0];
  kernel_function_mempools[KERNEL_FUNCTION_MEMPOOL_IDX_POOL_DDR_INPUT].addr = args[1];
  kernel_function_mempools[KERNEL_FUNCTION_MEMPOOL_IDX_POOL_DDR_OUTPUT].addr = args[2];
  kernel_function_mempools[KERNEL_FUNCTION_MEMPOOL_IDX_POOL_L2].addr = args[3];
  kernel_function_mempools[KERNEL_FUNCTION_MEMPOOL_IDX_POOL_L2_CONST].addr = args[4];

  // Initialise drivers
  ctf_trace_utils_init();
  mempool_init(kernel_function_mempools, KERNEL_FUNCTION_MEMPOOL_IDX_COUNT);
  task_handler_init();



  LOG_DBG("Run kernel_function (%d tasks)...", kernel_function_task_count);
  uint64_t start_tick_e2e = read_csr(cycle);
  TRACE_MK_KERNEL_START();
  task_handler_status_t status = task_handler_run_stream(TASK_HANDLER_STREAM_MODE_SW, &kernel_function_packed_tasks_stream, 0, 0);
  TRACE_MK_KERNEL_END();
  uint64_t end_tick_e2e = read_csr(cycle);
  LOG_WRN("[M] kernel_function %lu cycles", end_tick_e2e - start_tick_e2e);



  return (int)status;
}


